from AlgorithmImports import *
from datetime import timedelta, time


class FiveMinuteSpyCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute, Market.USA, False, 0).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA, False)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys().Strikes(-200, 200).Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.pending_signal = False
        self.held_contract = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        if self.Securities[self.spy].Invested:
            self.Debug("Unexpected SPY exercise/assignment position; liquidating SPY.")
            self.Liquidate(self.spy)

        self.ManageOpenOption(slice)

        if not self.pending_signal:
            return

        self.pending_signal = False

        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None or self.HasOpenEntryOrder():
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        spot = self.Securities[self.spy].Price
        if spot <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        eligible = [
            contract for contract in chain
            if (contract.Expiry.date() - self.Time.date()).days >= 7
        ]

        if not eligible:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        expiry = min(contract.Expiry.date() for contract in eligible)
        target_strike = spot * 1.01

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= target_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = min(candidates, key=lambda contract: (contract.Strike, str(contract.Symbol)))
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {expiry}, strike {selected.Strike}."
        )

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        prior_ready = self.fast.IsReady and self.slow.IsReady
        prior_fast = self.fast.Current.Value
        prior_slow = self.slow.Current.Value

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        bar_end = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_end <= time(14, 30)

        if (
            prior_ready
            and self.fast.IsReady
            and self.slow.IsReady
            and eligible_time
            and prior_fast <= prior_slow
            and self.fast.Current.Value > self.slow.Current.Value
        ):
            self.pending_signal = True

    def ManageOpenOption(self, slice: Slice):
        if self.held_contract is None:
            return

        expiry_date = self.held_contract.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.no_entry_date = self.Time.date()
            self.SubmitExit("Expiration processing")
            return

        if (
            self.Time.hour == 15
            and self.Time.minute == 45
            and self.Time.date() == self.PreviousTradingDay(expiry_date)
        ):
            self.SubmitExit("Pre-expiration time stop")
            return

        if self.entry_price is None or self.HasOpenExitOrder():
            return

        quote = slice.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason: str):
        if self.held_contract is None or self.HasOpenExitOrder():
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if self.entry_ticket is None or order.Id != self.entry_ticket.OrderId:
                self.Transactions.CancelOrder(order.Id)

        self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
        self.Debug(f"Exit submitted: {reason}, {self.held_contract}.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}."
                )
                self.held_contract = None
                self.entry_price = None
                self.entry_ticket = None
                self.exit_ticket = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_ticket = None

    def HasOpenEntryOrder(self) -> bool:
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status not in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ]
        )

    def HasOpenExitOrder(self) -> bool:
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status not in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ]
        )

    def PreviousTradingDay(self, expiry_date):
        expiry = datetime(expiry_date.year, expiry_date.month, expiry_date.day)
        previous_open = self.Securities[self.spy].Exchange.Hours.GetPreviousMarketOpen(
            expiry, False
        )
        return previous_open.date()

