from AlgorithmImports import *
from datetime import timedelta


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    def initialize(self):
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).symbol

        option = self.add_option("SPY", Resolution.MINUTE)
        option.set_filter(lambda universe: universe.strikes(-200, 200).expiration(0, 365))
        self.option_symbol = option.symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_signal = False

        self.held_contract = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.no_entry_today = False
        self.current_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.data_consolidated += self.on_five_minute_bar
        self.subscription_manager.add_consolidator(self.spy, consolidator)

    def on_five_minute_bar(self, sender, bar):
        self.fast.update(bar.end_time, bar.close)
        self.slow.update(bar.end_time, bar.close)

        if not self.fast.is_ready or not self.slow.is_ready:
            self.previous_fast = self.fast.current.value
            self.previous_slow = self.slow.current.value
            return

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and self.fast.current.value > self.slow.current.value
        )

        self.previous_fast = self.fast.current.value
        self.previous_slow = self.slow.current.value

        end_time = bar.end_time
        if bullish_cross and (
            (end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45))
            and (end_time.hour < 14 or (end_time.hour == 14 and end_time.minute <= 30))
        ):
            self.pending_entry_signal = True

    def on_data(self, slice):
        today = self.time.date()
        if self.current_date != today:
            self.current_date = today
            self.no_entry_today = False

        self.handle_unexpected_spy_position()
        self.handle_expiration_processing()
        self.handle_exit(slice)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.try_enter(slice)

    def try_enter(self, slice):
        if self.no_entry_today:
            return

        if self.held_contract is not None and self.portfolio[self.held_contract].invested:
            return

        if self.entry_order_id is not None:
            ticket = self.transactions.get_order_ticket(self.entry_order_id)
            if ticket is not None and ticket.status not in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ):
                return
            self.entry_order_id = None

        if self.option_symbol not in slice.option_chains:
            self.debug("Entry skipped: no SPY option chain in current Slice.")
            return

        spy_price = self.securities[self.spy].price
        if spy_price <= 0:
            self.debug("Entry skipped: invalid SPY price.")
            return

        earliest_expiry = today + timedelta(days=7)
        contracts = list(slice.option_chains[self.option_symbol])
        expiries = sorted({
            contract.expiry.date()
            for contract in contracts
            if contract.expiry.date() >= earliest_expiry
        })

        if not expiries:
            self.debug("Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = spy_price * 1.01
        candidates = [
            contract for contract in contracts
            if contract.expiry.date() == selected_expiry
            and contract.right == OptionRight.CALL
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug("Entry skipped: no eligible call at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.strike, str(contract.symbol))
        )[0]

        ticket = self.market_order(selected.symbol, 1)
        self.entry_order_id = ticket.order_id
        self.debug(
            f"Entry submitted: {selected.symbol}, expiry {selected.expiry.date()}, "
            f"strike {selected.strike}."
        )

    def handle_exit(self, slice):
        if self.held_contract is None or not self.portfolio[self.held_contract].invested:
            return

        if self.exit_order_id is not None:
            ticket = self.transactions.get_order_ticket(self.exit_order_id)
            if ticket is not None and ticket.status not in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ):
                return
            self.exit_order_id = None

        if self.is_pre_expiry_time_stop():
            self.submit_exit("pre-expiration time stop")
            return

        quote = self.current_contract_quote(slice, self.held_contract)
        if quote is None or self.entry_price is None or self.entry_price <= 0:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.submit_exit("50% profit target")

    def current_contract_quote(self, slice, symbol):
        if self.option_symbol not in slice.option_chains:
            return None

        for contract in slice.option_chains[self.option_symbol]:
            if contract.symbol == symbol:
                if contract.bid_price > 0 and contract.ask_price > 0:
                    return contract.bid_price, contract.ask_price
                return None
        return None

    def is_pre_expiry_time_stop(self):
        expiry_date = self.held_contract.id.date.date()
        prior_trading_day = expiry_date - timedelta(days=1)

        while not self.securities[self.spy].exchange.hours.is_date_open(prior_trading_day):
            prior_trading_day -= timedelta(days=1)

        return (
            self.time.date() == prior_trading_day
            and self.time.hour == 15
            and self.time.minute >= 45
        )

    def handle_expiration_processing(self):
        if self.held_contract is None or not self.portfolio[self.held_contract].invested:
            return

        if self.time.date() >= self.held_contract.id.date.date():
            self.no_entry_today = True
            self.submit_exit("expiration processing")

    def submit_exit(self, reason):
        if self.held_contract is None or not self.portfolio[self.held_contract].invested:
            return

        if self.exit_order_id is not None:
            existing = self.transactions.get_order_ticket(self.exit_order_id)
            if existing is not None and existing.status not in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ):
                return

        for order in self.transactions.get_open_orders(self.held_contract):
            if order.id != self.entry_order_id:
                self.transactions.cancel_order(order.id)

        quantity = self.portfolio[self.held_contract].quantity
        ticket = self.market_order(self.held_contract, -quantity)
        self.exit_order_id = ticket.order_id
        self.debug(f"Exit submitted: {reason}, {self.held_contract}.")

    def handle_unexpected_spy_position(self):
        if self.portfolio[self.spy].invested:
            quantity = self.portfolio[self.spy].quantity
            self.market_order(self.spy, -quantity)
            self.debug("Unexpected SPY exercise/assignment position detected; liquidating.")

    def on_order_event(self, order_event):
        if order_event.status != OrderStatus.FILLED:
            return

        if order_event.symbol.security_type == SecurityType.OPTION:
            if (
                self.entry_order_id is not None
                and order_event.order_id == self.entry_order_id
                and order_event.fill_quantity > 0
            ):
                self.held_contract = order_event.symbol
                self.entry_price = order_event.fill_price
                self.entry_order_id = None
                self.debug(
                    f"Entry filled: {self.held_contract} at {self.entry_price:.2f}."
                )

            if self.exit_order_id is not None and order_event.order_id == self.exit_order_id:
                self.debug(
                    f"Exit filled: {order_event.symbol} at {order_event.fill_price:.2f}."
                )
                if self.held_contract == order_event.symbol:
                    self.held_contract = None
                    self.entry_price = None
                self.exit_order_id = None

