            return

        if self.exit_order_id is not None:
            ticket = self.transactions.get_order_ticket(self.exit_order_id)
            if ticket is not None and ticket.status not in (
                OrderStatus.FILLED,
                OrderStatus.CANCELED,
                OrderStatus.INVALID
            ):
                return
            self.exit_order_id = None

        if self.is_pre_expiry_time_stop():
            self.submit_exit("pre-expiration time stop")
            return

        quote = self.current_contract_quote(slice, self.held_contract)
        if quote is None or self.entry_price is None or self.entry_price <= 0:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.submit_exit("50% profit target")

    def current_contract_quote(self, slice, symbol):
        if self.option_symbol not in slice.option_chains:
            return None

        for contract in slice.option_chains[self.option_symbol]:
            if contract.symbol == symbol:
                if contract.bid_price > 0 and contract.ask_price > 0:
                    return contract.bid_price, contract.ask_price
                return None
        return None

    def is_pre_expiry_time_stop(self):
        expiry_date = self.held_contract.id.date.date()
        prior_trading_day = expiry_date - timedelta(days=1)

        while not self.securities[self.spy].exchange.hours.is_date_open(prior_trading_day):
            prior_trading_day -= timedelta(days=1)

        return (
            self.time.date() == prior_trading_day
            and self.time.hour == 15
            and self.time.minute >= 45
        )

    def handle_expiration_processing(self):
        if self.held_contract is None or not self.portfolio[self.held_contract].invested:
            return

        if self.time.date() >= self.held_contract.id.date.date():
            self.no_entry_today = True
