            and not self._exit_order_is_open()
        ):
            self._submit_exit("15:45 pre-expiration time stop")

    def _process_expiration_protection(self):
        if not self._has_open_option_position() or self._held_contract is None:
            return

        expiration = self._held_contract.ID.Date.date()
        if self.Time.date() >= expiration:
            self._expiration_block_date = self.Time.date()
            if not self._exit_order_is_open():
                self._submit_exit("expiration protection")

    def _previous_trading_day(self, expiration_date):
        candidate = expiration_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_exit(self, reason):
        if not self._has_open_option_position():
            return

        for order in self.Transactions.GetOpenOrders(self._held_contract):
            self.Transactions.CancelOrder(order.Id, f"Replacing exit order: {reason}")

        quantity = self.Portfolio[self._held_contract].Quantity
        ticket = self.MarketOrder(self._held_contract, -quantity)
        self._exit_order_id = ticket.OrderId
        self.Debug(f"Submitted option exit ({reason}): {self._held_contract} at {self.Time}.")

    def _has_open_option_position(self):
        return self._held_contract is not None and self.Portfolio[self._held_contract].Invested

    def _exit_order_is_open(self):
        if self._exit_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self._exit_order_id)
        return order is not None and order.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self._entry_order_id:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self._held_contract = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self.Debug(
                    f"Call entry filled: {self._held_contract} at "
                    f"{self._entry_price:.2f} on {self.Time}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self._entry_order_id = None

        if order_event.OrderId == self._exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Option exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f} on {self.Time}.")
                self._held_contract = None
                self._entry_price = None
                self._exit_order_id = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self._exit_order_id = None

