from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)
        self.set_time_zone(TimeZones.NEW_YORK)

        self.spy = self.add_equity("SPY", Resolution.MINUTE).symbol
        self.securities[self.spy].set_data_normalization_mode(DataNormalizationMode.RAW)

        option = self.add_option("SPY", Resolution.MINUTE)
        option.set_filter(
            lambda universe: universe.include_weeklys()
            .strikes(-100, 100)
            .expiration(timedelta(days=0), timedelta(days=730))
        )
        self.option_symbol = option.symbol

        self.closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bar_end = None
        self.current_bar_count = 0
        self.last_minute_end = None

        self.held_contract = None
        self.held_expiry = None
        self.entry_price = None

        self.entry_ticket = None
        self.pending_entry_symbol = None
        self.pending_entry_expiry = None
        self.exit_ticket = None
        self.no_entry_date = None

    def on_data(self, data: Slice):
        self._handle_unexpected_spy_position()
        self._handle_held_option(data)

        spy_bar = data.bars.get(self.spy)
        if spy_bar is not None:
            self._update_five_minute_consolidation(spy_bar, data)

    def _update_five_minute_consolidation(self, bar: TradeBar, data: Slice):
        end_time = bar.end_time
        session_start = time(9, 31)
        session_end = time(16, 0)

        if end_time.time() < session_start or end_time.time() > session_end:
            return

        interval_end = end_time.replace(second=0, microsecond=0)
        minutes_to_add = (5 - interval_end.minute % 5) % 5
        interval_end += timedelta(minutes=minutes_to_add)

        if self.current_bar_end != interval_end:
            self.current_bar_end = interval_end
            self.current_bar_count = 0
            self.last_minute_end = None

        is_consecutive = (
            self.last_minute_end is None
            or end_time == self.last_minute_end + timedelta(minutes=1)
        )

        if not is_consecutive:
            self.current_bar_count = 0

        self.current_bar_count += 1
        self.last_minute_end = end_time

        if end_time != interval_end:
            return

        if self.current_bar_count == 5:
            self._on_five_minute_bar(interval_end, bar.close, data)

        self.current_bar_count = 0
        self.last_minute_end = None

    def _on_five_minute_bar(self, end_time: datetime, close: float, data: Slice):
        self.closes.add(float(close))

        if not self.closes.is_ready:
            return

        fast = sum(self.closes[i] for i in range(5)) / 5.0
        slow = sum(self.closes[i] for i in range(20)) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        entry_start = time(9, 45)
        entry_end = time(14, 30)
        if not bullish_cross or not (entry_start <= end_time.time() <= entry_end):
            return

        self._try_enter(data, close)

    def _try_enter(self, data: Slice, spy_price: float):
        if self.no_entry_date == self.time.date():
            return

        if self.held_contract is not None or self.pending_entry_symbol is not None:
            return

        expirations = set()
        eligible_contracts = []

        for chain in data.option_chains.values():
            for contract in chain:
                if contract.right != OptionRight.CALL:
                    continue

                dte = (contract.expiry.date() - self.time.date()).days
                if dte >= 7:
                    expirations.add(contract.expiry.date())
                    eligible_contracts.append(contract)

        if not expirations:
            self.debug("Skipped entry: no call expiration at least 7 calendar days away.")
            return

        selected_expiry_date = min(expirations)
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in eligible_contracts
            if contract.expiry.date() == selected_expiry_date
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug("Skipped entry: no qualifying call strike at selected expiration.")
            return

        contract = min(candidates, key=lambda x: (x.strike, str(x.symbol)))
        self.pending_entry_symbol = contract.symbol
        self.pending_entry_expiry = contract.expiry
        self.entry_ticket = self.market_order(contract.symbol, 1)

        self.debug(
            f"Entry submitted: {contract.symbol} "
            f"expiry {contract.expiry.date()} strike {contract.strike}"
        )

    def _handle_held_option(self, data: Slice):
        if self.held_contract is None:
            return

        if self.time.date() >= self.held_expiry.date():
            self.no_entry_date = self.time.date()
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(self.held_expiry.date())
        if self.time.time() == time(15, 45) and self.time.date() == previous_trading_day:
            self._submit_exit("pre-expiration time stop")
            return

        if self._has_open_exit_order():
            return

        contract = self._get_contract_from_slice(data, self.held_contract)
        if contract is None:
            return

        if contract.bid_price > 0 and contract.ask_price > 0:
            midpoint = (contract.bid_price + contract.ask_price) / 2.0
            if midpoint >= 1.5 * self.entry_price:
                self._submit_exit("50% profit target")

    def _previous_trading_day(self, expiry_date):
        expiry_start = datetime.combine(expiry_date, time.min)
        return self.securities[self.spy].exchange.hours.get_previous_market_open(
            expiry_start, False
        ).date()

    def _get_contract_from_slice(self, data: Slice, symbol: Symbol):
        for chain in data.option_chains.values():
            for contract in chain:
                if contract.symbol == symbol:
                    return contract
        return None

    def _submit_exit(self, reason: str):
        if self.held_contract is None or not self.portfolio[self.held_contract].invested:
            return

        for order in self.transactions.get_open_orders(self.held_contract):
            self.transactions.cancel_order(order.id)

        if self._has_open_exit_order():
            return

        quantity = -self.portfolio[self.held_contract].quantity
        if quantity != 0:
            self.exit_ticket = self.market_order(self.held_contract, quantity)
            self.debug(f"Exit submitted ({reason}): {self.held_contract}")

    def _has_open_exit_order(self):
        return (
            self.held_contract is not None
            and len(self.transactions.get_open_orders(self.held_contract)) > 0
        )

    def _handle_unexpected_spy_position(self):
        if not self.portfolio[self.spy].invested:
            return

        if len(self.transactions.get_open_orders(self.spy)) == 0:
            self.debug("Unexpected SPY exercise/assignment position; liquidating.")
            self.market_order(self.spy, -self.portfolio[self.spy].quantity)

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status == OrderStatus.FILLED:
            if (
                self.pending_entry_symbol is not None
                and order_event.symbol == self.pending_entry_symbol
                and order_event.fill_quantity > 0
            ):
                self.held_contract = order_event.symbol
                self.held_expiry = self.pending_entry_expiry
                self.entry_price = order_event.fill_price
                self.pending_entry_symbol = None
                self.pending_entry_expiry = None
                self.entry_ticket = None
                self.debug(
                    f"Entry filled: {self.held_contract} at {self.entry_price:.2f}"
                )
                return

            if (
                self.held_contract is not None
                and order_event.symbol == self.held_contract
                and order_event.fill_quantity < 0
                and not self.portfolio[self.held_contract].invested
            ):
                self.debug(
                    f"Exit filled: {self.held_contract} at {order_event.fill_price:.2f}"
                )
                self.held_contract = None
                self.held_expiry = None
                self.entry_price = None
                self.exit_ticket = None

        if (
            self.pending_entry_symbol is not None
            and self.entry_ticket is not None
            and order_event.order_id == self.entry_ticket.order_id
            and order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID)
        ):
            self.pending_entry_symbol = None
            self.pending_entry_expiry = None
            self.entry_ticket = None

